    "折々": ["遠くで暮らす祖母は、折々に季節の便りを送ってくれる。","My grandmother, who lives far away, sends seasonal letters from time to time."],
    "時折": ["真剣な会議の最中でも、彼は時折冗談を挟んで場を和ませる。","Even in the middle of a serious meeting, he occasionally slips in a joke to lighten the mood."],
    "逐次的": ["大規模な改修は無理なので、逐次的に設備を入れ替えていく方針だ。","A large-scale renovation isn't feasible, so the plan is to replace the equipment sequentially."],
    "恒常": ["一時的な対策ではなく、恒常的に人手不足を解消する仕組みが要る。","We need a system that resolves the labor shortage permanently, not just a temporary fix."],
    "恒久": ["紛争を繰り返さないため、恒久的な平和の枠組みが模索されている。","To avoid repeated conflict, a permanent framework for peace is being sought."],
    "一時的": ["円安は一時的な現象だと楽観していたが、長期化しそうだ。","I was optimistic that the weak yen was a temporary phenomenon, but it looks set to last."],
    "暫定": ["正式な体制が決まるまで、彼が暫定の責任者を務めることになった。","Until the formal structure is decided, he will serve as the provisional person in charge."],
    "継続": ["小さな努力でも、継続することが何より大事だと痛感している。","Even small efforts—I keenly feel that continuing them matters more than anything."],
