    "遠因": ["人手不足が事故の遠因になっていたと考えられる。","The labor shortage is thought to have been an underlying cause of the accident."],
    "主因": ["売上不振の主因は商品開発の遅れにある。","The main cause of the poor sales lies in the delay in product development."],
    "真因": ["表面的な対策ではなく真因を突き止めるべきだ。","We should pinpoint the true cause rather than apply superficial fixes."],
    "如実": ["彼の表情が当時の苦労を如実に物語っていた。","His expression vividly conveyed the hardships of those days."],
    "明白": ["契約違反であることは誰の目にも明白だ。","It is obvious to anyone that this is a breach of contract."],
    "歴然": ["新旧モデルの性能差は歴然としていた。","The performance gap between the old and new models was unmistakable."],
    "明瞭": ["説明が明瞭で、初心者でもすぐ理解できた。","The explanation was so clear that even beginners understood right away."],
