    "差し詰め": ["彼は差し詰めこのチームの司令塔といったところだ。","He is, in short, something like the command tower of this team."],
    "ともすれば": ["在宅勤務だと、ともすれば仕事と生活の境目が曖昧になる。","Working from home, the line between work and life is apt to blur."],
    "往々にして": ["急いで決めた計画は、往々にして後で破綻する。","Plans decided in haste often fall apart later."],
    "かろうじて": ["終電にかろうじて間に合い、家まで歩かずに済んだ。","I barely made the last train and was spared having to walk home."],
    "辛うじて": ["崖の途中で木につかまり、辛うじて転落を免れた。","Grabbing a tree partway down the cliff, I narrowly avoided falling."],
    "鑑みる": ["昨今の経済情勢に鑑みて、賞与の支給は見送ることになった。","In light of the recent economic situation, we have decided to forgo paying bonuses."],
    "即する": ["机上の理屈ではなく、現場の実情に即した対策が要る。","We need measures that conform to the realities on the ground, not desk theory."],
    "準ずる": ["契約社員の待遇も、原則として正社員に準ずるものとする。","The treatment of contract employees shall, in principle, correspond to that of regular employees."],
    "相俟って": ["円安と原料高が相俟って、外食産業の利益を圧迫している。","The weak yen coupled with rising raw material costs is squeezing the restaurant industry's profits."],
    "伴って": ["気温の上昇に伴って、電力需要も急激に増えてきた。","Accompanying the rise in temperature, electricity demand has surged."],
    "先立って": ["会議に先立って、資料に目を通しておいてください。","Prior to the meeting, please look over the materials."],
    "際して": ["新店舗の開店に際して、ささやかな記念品をご用意しました。","On the occasion of the new store's opening, we have prepared a small commemorative gift."],
    "当たって": ["新しい事業を始めるに当たって、銀行に融資を相談した。","Before launching the new business, I consulted the bank about a loan."],
    "もって": ["契約は本日をもって正式に解除されます。","The contract will be officially terminated as of today."],
    "ならびに": ["関係者ならびにご家族の皆様にお礼申し上げます。","I would like to thank everyone involved as well as their families."],
    "および": ["申請書および身分証明書を窓口にご提出ください。","Please submit the application form and an ID document at the counter."],
    "かつ": ["彼の説明は簡潔かつ的確で、誰もが納得した。","His explanation was concise and accurate, and everyone was convinced."],
    "ただし": ["返品は受け付けます。ただし、未開封のものに限ります。","Returns are accepted, provided that the item is unopened."],
    "なお": ["会議は三時に始まります。なお、資料は当日配布します。","The meeting starts at three. Note that materials will be handed out that day."],
    "ゆえに": ["彼は無口だ。それゆえに誤解されることも多い。","He is taciturn, and for that reason he is often misunderstood."],
    "したがって": ["原料費が高騰した。したがって価格を見直さざるを得ない。","Raw material costs have soared, so we have no choice but to revise prices."],
    "よって": ["以上の理由によって、本提案は却下されました。","For the above reasons, this proposal was rejected."],
    "いわゆる": ["彼はいわゆる仕事人間で、休日もパソコンを離さない。","He's what you'd call a workaholic; he won't put down his laptop even on days off."],
    "所謂": ["この地域は所謂限界集落で、住民の高齢化が深刻だ。","This area is a so-called marginal village, with severe aging among residents."],
    "いかなる": ["いかなる理由があっても、暴力は許されない。","No matter the reason, violence cannot be tolerated."],
    "賜物": ["今回の成功は、チーム全員の努力の賜物です。","This success is the fruit of the entire team's efforts."],
    "所存": ["今後とも誠心誠意努めてまいる所存でございます。","I intend to continue serving with utmost sincerity."],
    "次第": ["天候次第では、登山を中止することもあります。","Depending on the weather, the climb may be called off."],
    "旨": ["値上げの旨を取引先に文書で通知した。","We notified our clients in writing of the price increase."],
    "如く": ["彼女は水を得た魚の如く、舞台で生き生きと演じた。","She performed on stage vividly, like a fish in water."],
    "べく": ["締め切りに間に合わせるべく、徹夜で原稿を書き上げた。","To make the deadline, I stayed up all night finishing the manuscript."],
    "ざるを得ない": ["証拠を突きつけられ、彼も非を認めざるを得なかった。","Confronted with the evidence, even he had to admit his fault."],
    "山岳": ["この一帯は山岳地帯で、冬は積雪で道が閉ざされる。","This whole area is mountainous, and roads close under snow in winter."],
    "渓谷": ["紅葉に染まった渓谷を、川に沿って歩いた。","We walked along the river through a valley dyed in autumn colors."],
    "峡谷": ["バスは断崖の続く峡谷沿いの道をゆっくり進んだ。","The bus crept along a road beside a gorge lined with cliffs."],
    "湿原": ["夏の湿原には、可憐な高山植物が一面に咲く。","In summer the marshland is covered with delicate alpine flowers."],
    "干潟": ["干潟では渡り鳥が泥の中の餌をついばんでいた。","On the tidal flat, migratory birds were pecking at food in the mud."],
    "岬": ["岬の先端に立つ灯台が、夜の海を照らしていた。","The lighthouse at the tip of the cape lit up the sea at night."],
    "岩礁": ["濃霧の中、船は岩礁に乗り上げて座礁した。","In dense fog, the ship ran aground on a reef."],
    "潮流": ["時代の潮流に乗り遅れた企業は次々と姿を消した。","Companies that failed to ride the trend of the times vanished one after another."],
    "噴火": ["火山が突然噴火し、住民は急いで避難した。","The volcano erupted suddenly, and residents evacuated in a hurry."],
    "地殻": ["地震は地殻のずれによって引き起こされる。","Earthquakes are caused by slippage in the earth's crust."],
    "震源": ["今回の地震の震源は、沖合の深い海底だった。","The epicenter of this earthquake was deep on the seafloor offshore."],
