    "秘境": ["車も入れない秘境の温泉に、徒歩で三時間かけて向かった。","We walked three hours to reach a hidden hot spring no car can reach."],
    "芸術": ["彼の作品は、芸術と実用が見事に融合している。","His work beautifully blends art and practicality."],
    "美学": ["無駄を削ぎ落とすことに、彼独自の美学がある。","He has his own aesthetic in stripping away everything unnecessary."],
    "粋": ["着物の着こなしに、その女将の粋が表れていた。","The way she wore her kimono showed the landlady's elegant taste."],
    "伝承": ["この祭りは千年にわたって村に伝承されてきた。","This festival has been handed down in the village for a thousand years."],
    "継承": ["創業者の理念は、息子にしっかりと継承された。","The founder's philosophy was firmly passed on to his son."],
    "創作": ["締め切りに追われ、創作意欲がすっかり萎えてしまった。","Hounded by deadlines, my creative drive has completely faded."],
    "描写": ["小説の戦場の描写は、あまりに生々しくて息をのんだ。","The novel's depiction of the battlefield was so vivid it took my breath away."],
    "表現": ["言葉では表現しきれないほどの感動を覚えた。","I was moved beyond what words could express."],
    "韻律": ["この詩は独特の韻律が心地よく、声に出して読みたくなる。","This poem's distinctive meter is so pleasant it makes you want to read it aloud."],
    "旋律": ["どこか懐かしい旋律が、ラジオから流れてきた。","A somehow nostalgic melody drifted from the radio."],
