    "斬新": ["そのデザインは斬新すぎて、社内では賛否が分かれた。","The design was so novel that opinions split within the company."],
    "学識": ["教授の深い学識に、学生たちは圧倒された。","The students were overwhelmed by the professor's deep erudition."],
    "学府": ["その大学は、長く国内最高学府として名を馳せてきた。","That university has long been renowned as the nation's highest seat of learning."],
    "講義": ["教授の講義はわかりやすく、毎回教室が満員になる。","The professor's lectures are easy to follow, filling the room every time."],
    "講座": ["市民向けの料理講座に申し込み、毎週通っている。","I signed up for a citizens' cooking course and attend weekly."],
