    "博識": ["先生は歴史から園芸まで、本当に博識で話を聞くだけで楽しい。","The teacher is so erudite, from history to gardening, that just listening to him is a treat."],
    "碩学": ["その分野では右に出る者のいない碩学が、惜しまれつつ世を去った。","An unrivaled scholar in that field passed away, deeply mourned."],
    "権威": ["彼は感染症研究の権威として、各国から助言を求められている。","As an authority on infectious disease research, he is consulted by countries around the world."],
    "論拠": ["君の主張は感情論ばかりで、肝心の論拠が示されていない。","Your argument is all emotion; the crucial grounds for it are never laid out."],
